-- Run in Supabase SQL Editor. Use a NEW project. All admin RPCs require membership in admin_users.
create extension if not exists pgcrypto;
create table if not exists public.event_config (id int primary key default 1 check(id=1), capacity int not null default 200 check(capacity>0), price_per_guest numeric(10,2) not null default 20, booking_open boolean not null default true);
insert into public.event_config(id,capacity,price_per_guest) values(1,200,20) on conflict(id) do nothing;
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade);
create table if not exists public.bookings(id uuid primary key default gen_random_uuid(),reference text unique not null default ('NOC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,9))),email text,guest_count int not null check(guest_count>=2 and guest_count%2=0),status text not null check(status in('pending','confirmed','rejected','cancelled')) default 'pending',complimentary boolean not null default false,amount_due numeric(10,2) not null default 0,amount_collected numeric(10,2) not null default 0,entry_token uuid not null default gen_random_uuid(),checked_in_at timestamptz,notes text,created_at timestamptz not null default now());
create table if not exists public.guests(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id) on delete cascade,full_name text not null,phone text not null);
create table if not exists public.notifications(id bigint generated always as identity primary key,title text not null,message text not null,booking_id uuid references public.bookings(id),read_at timestamptz,created_at timestamptz default now());
create index if not exists bookings_status_idx on public.bookings(status);
create index if not exists guests_booking_idx on public.guests(booking_id);
alter table public.event_config enable row level security;
alter table public.admin_users enable row level security;
alter table public.bookings enable row level security;
alter table public.guests enable row level security;
alter table public.notifications enable row level security;
revoke all on public.event_config,public.admin_users,public.bookings,public.guests,public.notifications from anon,authenticated;
create or replace function public.is_admin() returns boolean language sql security definer set search_path='' stable as $$select exists(select 1 from public.admin_users where user_id=auth.uid())$$;
revoke all on function public.is_admin() from public,anon;grant execute on function public.is_admin() to authenticated;
create or replace function public.public_capacity() returns jsonb language sql security definer set search_path='' stable as $$select jsonb_build_object('total',c.capacity,'used',coalesce((select sum(b.guest_count) from public.bookings b where b.status='confirmed'),0),'remaining',greatest(0,c.capacity-coalesce((select sum(b.guest_count) from public.bookings b where b.status='confirmed'),0))) from public.event_config c where c.id=1$$;
create or replace function public.validate_guests(p_guests jsonb) returns integer language plpgsql security definer set search_path='' as $$declare n int;g jsonb;begin if jsonb_typeof(p_guests) is distinct from 'array' then raise exception 'Guest list must be an array';end if;n:=jsonb_array_length(p_guests);if n<2 or n%2<>0 or n>200 then raise exception 'Guests must be an even number between 2 and 200';end if;for g in select value from jsonb_array_elements(p_guests) loop if length(trim(coalesce(g->>'name','')))<2 or length(trim(coalesce(g->>'name','')))>100 or length(trim(coalesce(g->>'phone','')))<6 or length(trim(coalesce(g->>'phone','')))>30 then raise exception 'Each guest requires a valid name and phone';end if;end loop;return n;end$$;
revoke all on function public.validate_guests(jsonb) from public,anon,authenticated;
create or replace function public.create_public_booking(p_guests jsonb,p_email text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare n int;b public.bookings%rowtype;g jsonb;cfg public.event_config%rowtype;begin n:=public.validate_guests(p_guests);if length(coalesce(p_email,''))>254 then raise exception 'Email too long';end if;select * into cfg from public.event_config where id=1;if not cfg.booking_open then raise exception 'Reservations are closed';end if;insert into public.bookings(guest_count,email,amount_due) values(n,nullif(trim(p_email),''),n*cfg.price_per_guest) returning * into b;for g in select value from jsonb_array_elements(p_guests) loop insert into public.guests(booking_id,full_name,phone) values(b.id,trim(g->>'name'),trim(g->>'phone'));end loop;insert into public.notifications(title,message,booking_id) values('New reservation',b.reference||' requests '||n||' guests',b.id);return jsonb_build_object('id',b.id,'reference',b.reference);end$$;
create or replace function public.get_ticket(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare b public.bookings%rowtype;begin select * into b from public.bookings where id=p_id;if not found then return null;end if;return jsonb_build_object('reference',b.reference,'status',b.status,'guest_count',b.guest_count,'amount_due',b.amount_due,'entry_token',case when b.status='confirmed' then b.entry_token::text else null end);end$$;
create or replace function public.admin_bookings() returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin if not public.is_admin() then raise exception 'Access denied';end if;select coalesce(jsonb_agg(x order by x.created_at desc),'[]'::jsonb) into result from (select b.*,coalesce((select string_agg(g.full_name,', ' order by g.full_name) from public.guests g where g.booking_id=b.id),'') guest_names from public.bookings b)x;return result;end$$;
create or replace function public.admin_notifications() returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin if not public.is_admin() then raise exception 'Access denied';end if;select coalesce(jsonb_agg(to_jsonb(n) order by n.created_at desc),'[]'::jsonb) into result from (select * from public.notifications order by created_at desc limit 100)n;return result;end$$;
create or replace function public.admin_mark_notification_read(p_id bigint) returns void language plpgsql security definer set search_path='' as $$begin if not public.is_admin() then raise exception 'Access denied';end if;update public.notifications set read_at=now() where id=p_id;end$$;
create or replace function public.admin_update_booking(p_id uuid,p_action text) returns void language plpgsql security definer set search_path='' as $$declare b public.bookings%rowtype;cfg public.event_config%rowtype;used int;begin if not public.is_admin() then raise exception 'Access denied';end if;select * into cfg from public.event_config where id=1 for update;select * into b from public.bookings where id=p_id for update;if not found then raise exception 'Booking not found';end if;if p_action='approve' then if b.status<>'pending' then raise exception 'Booking not pending';end if;select coalesce(sum(guest_count),0) into used from public.bookings where status='confirmed';if used+b.guest_count>cfg.capacity then raise exception 'Capacity exceeded';end if;update public.bookings set status='confirmed' where id=p_id;elsif p_action='reject' then if b.status<>'pending' then raise exception 'Booking not pending';end if;update public.bookings set status='rejected' where id=p_id;elsif p_action='cancel' then if b.status<>'confirmed' or b.checked_in_at is not null then raise exception 'Cannot cancel this booking';end if;update public.bookings set status='cancelled' where id=p_id;elsif p_action='collect' then if b.status<>'confirmed' or b.complimentary or b.checked_in_at is not null then raise exception 'Not eligible for collection';end if;update public.bookings set amount_collected=amount_due where id=p_id;else raise exception 'Unknown action';end if;insert into public.notifications(title,message,booking_id) values('Booking updated',b.reference||': '||p_action,p_id);end$$;
create or replace function public.admin_create_comp(p_guests jsonb,p_note text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare n int;cfg public.event_config%rowtype;used int;b public.bookings%rowtype;g jsonb;begin if not public.is_admin() then raise exception 'Access denied';end if;n:=public.validate_guests(p_guests);select * into cfg from public.event_config where id=1 for update;select coalesce(sum(guest_count),0) into used from public.bookings where status='confirmed';if used+n>cfg.capacity then raise exception 'Capacity exceeded';end if;insert into public.bookings(guest_count,status,complimentary,amount_due,notes) values(n,'confirmed',true,0,left(p_note,1000)) returning * into b;for g in select value from jsonb_array_elements(p_guests) loop insert into public.guests(booking_id,full_name,phone) values(b.id,trim(g->>'name'),trim(g->>'phone'));end loop;insert into public.notifications(title,message,booking_id) values('House reservation',b.reference||': '||n||' complimentary guests',b.id);return jsonb_build_object('id',b.id,'reference',b.reference);end$$;
create or replace function public.admin_checkin(p_token text) returns integer language plpgsql security definer set search_path='' as $$declare b public.bookings%rowtype;begin if not public.is_admin() then raise exception 'Access denied';end if;select * into b from public.bookings where entry_token::text=p_token for update;if not found or b.status<>'confirmed' then raise exception 'Invalid or unconfirmed ticket';end if;if b.checked_in_at is not null then raise exception 'Ticket already used';end if;if not b.complimentary and b.amount_collected<b.amount_due then raise exception 'Collect payment first';end if;update public.bookings set checked_in_at=now() where id=b.id;insert into public.notifications(title,message,booking_id) values('Guest entry',b.reference||': '||b.guest_count||' guests checked in',b.id);return b.guest_count;end$$;
revoke all on function public.public_capacity(),public.create_public_booking(jsonb,text),public.get_ticket(uuid),public.admin_bookings(),public.admin_notifications(),public.admin_mark_notification_read(bigint),public.admin_update_booking(uuid,text),public.admin_create_comp(jsonb,text),public.admin_checkin(text) from public;
grant execute on function public.public_capacity(),public.create_public_booking(jsonb,text),public.get_ticket(uuid) to anon,authenticated;
grant execute on function public.admin_bookings(),public.admin_notifications(),public.admin_mark_notification_read(bigint),public.admin_update_booking(uuid,text),public.admin_create_comp(jsonb,text),public.admin_checkin(text) to authenticated;
-- For dashboard realtime, permit only admin subscribers to read notifications.
create policy "admin notifications read" on public.notifications for select to authenticated using(public.is_admin());
grant select on public.notifications to authenticated;
alter publication supabase_realtime add table public.notifications;
